fig,ax=plt.subplots(1,3,figsize=(15,4));h=m['confidence_histogram'];ax[0].bar(h['edges'][:-1],h['counts'],width=.05,align='edge');ax[0].set(xlabel='Maximum class probability',ylabel='VAL labeled-frame pixels',title='Confidence (fixed recipe)')
